import copy
import json
import os
import sqlite3
from pathlib import Path

INITIAL = {
    'a': {'id': 'a', 'title': 'North', 'body': 'old-a', 'revision': 0},
    'b': {'id': 'b', 'title': 'South', 'body': 'old-b', 'revision': 0},
}

class Conflict(Exception):
    pass

class Snapshot:
    def __init__(self, directory):
        self.path = Path(directory) / 'notes.json'

    def seed(self):
        self.path.write_text(json.dumps(INITIAL), encoding='utf-8')

    def read(self):
        return json.loads(self.path.read_text(encoding='utf-8'))

    def save(self, loaded, changes, crash=False):
        updated = copy.deepcopy(loaded)
        for note_id, body in changes.items():
            updated[note_id]['body'] = body
            updated[note_id]['revision'] += 1
        staging = self.path.with_suffix('.stage')
        with staging.open('w', encoding='utf-8') as stream:
            json.dump(updated, stream)
            stream.flush()
            os.fsync(stream.fileno())
        if crash:
            os._exit(23)
        os.replace(staging, self.path)

class Sqlite:
    def __init__(self, directory, guarded=False):
        self.path = Path(directory) / 'notes.db'
        self.guarded = guarded

    def connect(self):
        connection = sqlite3.connect(self.path, isolation_level=None)
        connection.execute('PRAGMA journal_mode=DELETE')
        connection.execute('PRAGMA synchronous=FULL')
        return connection

    def seed(self):
        connection = self.connect()
        try:
            connection.execute('CREATE TABLE notes (id TEXT PRIMARY KEY, title TEXT, body TEXT, revision INTEGER)')
            connection.executemany('INSERT INTO notes VALUES (:id, :title, :body, :revision)', INITIAL.values())
        finally:
            connection.close()

    def read(self):
        connection = self.connect()
        connection.row_factory = sqlite3.Row
        try:
            return {row['id']: dict(row) for row in connection.execute('SELECT * FROM notes')}
        finally:
            connection.close()

    def save(self, loaded, changes, crash=False):
        connection = self.connect()
        try:
            connection.execute('BEGIN IMMEDIATE')
            for index, (note_id, body) in enumerate(changes.items()):
                revision, = connection.execute('SELECT revision FROM notes WHERE id=?', (note_id,)).fetchone()
                if self.guarded and revision != loaded[note_id]['revision']:
                    raise Conflict(note_id)
                connection.execute('UPDATE notes SET body=?, revision=revision+1 WHERE id=?', (body, note_id))
                if crash and index == 0:
                    os._exit(23)
            connection.execute('COMMIT')
        except BaseException:
            if connection.in_transaction:
                connection.execute('ROLLBACK')
            raise
        finally:
            connection.close()

def adapter(name, directory):
    if name == 'snapshot':
        return Snapshot(directory)
    return Sqlite(directory, guarded=name == 'sqlite-guarded')

