import argparse
import json
import sqlite3
import subprocess
import sys
from pathlib import Path
from storage import Conflict, adapter

def run(output):
    output.mkdir(parents=True, exist_ok=False)
    summary = {'python': sys.version.split()[0], 'sqlite': sqlite3.sqlite_version, 'adapters': {}}
    for backend in ('snapshot', 'sqlite', 'sqlite-guarded'):
        results = {}
        for scenario in ('reopen', 'different-note-windows', 'same-note-windows', 'interrupted-pair'):
            directory = output / backend / scenario
            directory.mkdir(parents=True)
            store = adapter(backend, directory)
            store.seed()
            if scenario == 'reopen':
                store.save(store.read(), {'a': 'saved-offline'})
            elif scenario in ('different-note-windows', 'same-note-windows'):
                first, second = store.read(), store.read()
                store.save(first, {'a': 'first-edit'})
                try:
                    store.save(second, {'b' if scenario == 'different-note-windows' else 'a': 'second-edit'})
                    results[scenario] = {'second_save': 'accepted'}
                except Conflict:
                    results[scenario] = {'second_save': 'conflict'}
            else:
                completed = subprocess.run([sys.executable, str(Path(__file__).resolve()),
                    '--crash-worker', backend, str(directory.resolve())], check=False)
                if completed.returncode != 23:
                    raise RuntimeError(f'crash worker exited {completed.returncode}, expected 23')
                results[scenario] = {'worker_exit': completed.returncode}
            results.setdefault(scenario, {})['reopened'] = adapter(backend, directory).read()
        summary['adapters'][backend] = results
    (output / 'summary.json').write_text(json.dumps(summary, indent=2) + '\n', encoding='utf-8')
    return summary

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--output', type=Path)
    parser.add_argument('--crash-worker', nargs=2, metavar=('BACKEND', 'DIRECTORY'))
    arguments = parser.parse_args()
    if arguments.crash_worker:
        backend, directory = arguments.crash_worker
        store = adapter(backend, directory)
        store.save(store.read(), {'a': 'new-a', 'b': 'new-b'}, crash=True)
        raise SystemExit('crash injection did not terminate the worker')
    if arguments.output is None:
        parser.error('--output is required')
    print(json.dumps(run(arguments.output), indent=2))
